def strip_comments(code):
    """Remove both // and /* */ comments from JS code."""
    # This is a simple approach; handle string literals carefully
    result = []
    i = 0
    while i < len(code):
        if code[i] == '"' or code[i] == "'" or code[i] == '`':
            # string literal
            quote = code[i]
            result.append(code[i])
            i += 1
            while i < len(code):
                if code[i] == '\\':
                    result.append(code[i])
                    i += 1
                    if i < len(code):
                        result.append(code[i])
                        i += 1
                elif code[i] == quote:
                    result.append(code[i])
                    i += 1
                    break
                else:
                    result.append(code[i])
                    i += 1
        elif code[i:i+2] == '//':
            # skip to end of line
            while i < len(code) and code[i] != '\n':
                i += 1
        elif code[i:i+2] == '/*':
            # skip to */
            i += 2
            while i < len(code) - 1:
                if code[i:i+2] == '*/':
                    i += 2
                    break
                i += 1
        else:
            result.append(code[i])
            i += 1
    return ''.join(result)

