def read_env_file(path):
    vals = {}
    for line in path.read_text().splitlines():
        line=line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' in line:
            k,v = line.split('=',1)
            vals[k.strip()] = v.strip().strip('"').strip("'")
    return vals

def effective_settings(svc_dir: pathlib.Path):
    # find config file
    candidates = ['config.json','config.yaml','config.toml','config.ini','service.env']
    config_path = None
    for c in candidates:
        p = svc_dir / c
        if p.exists():
            config_path = p
            break
    settings = {}
    if config_path:
        ext = config_path.suffix.lower()
        text = config_path.read_text()
        if ext == '.json':
            data = json.loads(text)
            settings = {k.upper(): v for k,v in data.items()}
        elif ext in ('.yaml','.yml'):
            data = yaml.safe_load(text)
            if isinstance(data, dict):
                settings = {k.upper(): v for k,v in data.items()}
        elif ext == '.toml':
            data = tomli.loads(text.encode())
            if isinstance(data, dict):
                settings = {k.upper(): v for k,v in data.items()}
        elif ext == '.ini':
            cp = configparser.ConfigParser()
            cp.read_string(text)
            # assume default section or any section; flatten
            for sec in cp.sections():
                for k,v in cp.items(sec):
                    settings[k.upper()] = v
            # also default section
            for k,v in cp.items('DEFAULT'):
                settings[k.upper()] = v
        elif config_path.name == 'service.env':
            settings = read_env_file(config_path)
    # override
    override_path = svc_dir / 'override.env'
    if override_path.exists():
        overrides = read_env_file(override_path)
        for k in ['PORT','TLS','MAX_CONNECTIONS']:
            if k in overrides:
                settings[k] = overrides[k]
    return settings

