# Define the transformation logic
def migrate_config(data):
    if data.get("version") == 2:
        return None  # Already v2, don't touch

    new_data = {}
    for key, value in data.items():
        if key == "version":
            new_data["version"] = 2
        elif key == "timeoutMs":
            new_data["timeout_s"] = value / 1000.0
        elif key == "retry":
            new_data["retry"] = {
                "attempts": value["count"],
                "backoff_s": value["backoffMs"] / 1000.0
            }
        elif key == "owners":
            if isinstance(value, str):
                emails = [email.strip().lower() for email in value.split(",")]
                emails = [email for email in emails if email]
                new_data["owners"] = emails
            else:
                new_data["owners"] = value
        else:
            new_data[key] = value

    # Add default retry if missing
    if "retry" not in new_data:
        new_data["retry"] = {"attempts": 0, "backoff_s": 0}

    return new_data

