        all_files.append(path)

print("All files under configs/:")
for f in sorted(all_files):
    print(f"  {f}")

# Check for any backup-like files
backups = [f for f in all_files if any(ext in f.lower() for ext in [".bak", ".backup", ".orig", ".old", "~"])]
if backups:
    print("\nWARNING: Backup files found:")
    for b in backups:
        print(f"  {b}")
else:
    print("\nNo backup files found. Clean migration.")
